const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='countschedula-pilot-v1',names=['Emma Wilson','Sarah Chen','Olivia Brooks','Rachel Morgan','Mia Patel','Hannah Davis','Claire Bennett','Ava Thompson'];
const depts=[{id:'willow',name:'Jones Team · Labor & Delivery',org:'Jones Team'},{id:'river',name:'Boehm Team · Birth Center',org:'Boehm Team'}];
let state,view='Schedule',dept='willow',cursor=new Date(2026,10,1),mode='Month',selectedOrgs=['willow'],filter='',history=[];
function seed(){return {providers:names.map((name,i)=>({id:'p'+i,name,role:'CNM',target:i===7?6:10,max:14,nights:true,affiliations:i<3?['willow','river']:['willow']})),assignments:[],requests:[{id:'r1',provider:'p2',start:'2026-11-12',end:'2026-11-14',status:'Pending',reason:'Family trip'},{id:'r2',provider:'p4',start:'2026-11-23',end:'2026-11-25',status:'Approved',reason:'Personal time'}],rules:{rest:12,consecutive:3,dayCoverage:1,nightCoverage:1},periods:{},audit:[]}}
const CLOUD=typeof window!=='undefined'&&window.COUNTSCHEDULA_CONFIG&&window.CountSchedulaCloud||null,SAFE_ID=/^[A-Za-z0-9_-]{1,64}$/;
let rotationSel={}; // memory-only: chosen rotation per team (department id)
try{state=CLOUD?{...seed(),providers:[],assignments:[],requests:[]}:JSON.parse(localStorage.getItem(KEY))||seed()}catch{state=seed()}

function defaultShiftTypes(rules={}){return [
{id:'day',name:'Day',start:'07:00',end:'19:00',color:'#6b9b69',coverage:rules.dayCoverage??1,night:false,active:true},
{id:'night',name:'Night',start:'19:00',end:'07:00',color:'#8a79b2',coverage:rules.nightCoverage??1,night:true,active:true},
{id:'clinic-am',name:'Clinic AM',start:'08:00',end:'12:00',color:'#5c9db0',coverage:0,night:false,active:true},
{id:'clinic-pm',name:'Clinic PM',start:'13:00',end:'17:00',color:'#b28e56',coverage:0,night:false,active:true},
{id:'triage',name:'Triage',start:'09:00',end:'21:00',color:'#b47783',coverage:0,night:false,active:true},
{id:'flex',name:'Flex',start:'11:00',end:'19:00',color:'#728caf',coverage:0,night:false,active:true}]}
function migrate(data){if(!data.shiftTypes)data.shiftTypes=defaultShiftTypes(data.rules);for(let event of data.audit||[]){if(typeof event.text==='string')event.text=event.text.replace(/Willow Women[’']s Health|Willow/g,'Jones Team').replace(/Riverside Hospital|Riverside/g,'Boehm Team')}if(!Array.isArray(data.rotations))data.rotations=[];for(let r of data.rotations)if(r&&!Array.isArray(r.holidays))r.holidays=[];if(!data.rotationDefaults||typeof data.rotationDefaults!=='object')data.rotationDefaults={};if(!Array.isArray(data.holidayHistory))data.holidayHistory=[];for(let p of data.providers||[]){if(p.rotationTarget==null&&Number.isFinite(p.target))p.rotationTarget=p.target*2;if(p.rotationMax==null&&Number.isFinite(p.max))p.rotationMax=p.max*2}return data}
state=migrate(state);
function shiftType(id){return state.shiftTypes.find(t=>t.id===id)}
function activeTypes(){return state.shiftTypes.filter(t=>t.active)}
function shiftName(id){return shiftType(id)?.name||id}
function minutes(t){let [h,m]=t.split(':').map(Number);return h*60+m}
function shiftHours(id){let t=shiftType(id);if(!t)return 0;return ((minutes(t.end)-minutes(t.start)+1440)%1440||1440)/60}
function clock(t){let [h,m]=t.split(':').map(Number);return (h%12||12)+(m?':'+String(m).padStart(2,'0'):'')+(h<12?'a':'p')}
function shiftRange(t){return clock(t.start)+'–'+clock(t.end)}
function shiftOptions(selected){return state.shiftTypes.filter(t=>t.active||t.id===selected).map(t=>`<option value="${t.id}" ${t.id===selected?'selected':''}>${esc(t.name)} · ${shiftRange(t)}${t.active?'':' (inactive)'}</option>`).join('')}

function iso(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function date(s){return new Date(s+'T00:00:00')}function plus(s,n){let d=date(s);d.setDate(d.getDate()+n);return iso(d)}function monthKey(d=cursor){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}function periodKey(){return dept+':'+monthKey()}function locked(){return periodStatus(period())==='Published'}
function persist(){if(CLOUD)return CLOUD.save();try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){toast('Could not save in this browser (storage full or blocked). Download a backup now to keep your work.')}}function audit(text){state.audit.unshift({text,time:new Date().toISOString()});state.audit=state.audit.slice(0,300);if(CLOUD)CLOUD.note(text)}function commit(text){audit(text);persist();render()}function checkpoint(){history.push(JSON.stringify(state));if(history.length>20)history.shift()}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4200)}
function provider(id){return state.providers.find(p=>p.id===id)}function initials(p){return p.name.split(' ').map(s=>s[0]).slice(0,2).join('')}function relevant(department=dept,range=period(department)){return state.assignments.filter(a=>a.dept===department&&a.date>=range.start&&a.date<=range.end)}function daysInMonth(){return new Date(cursor.getFullYear(),cursor.getMonth()+1,0).getDate()}function totalSlots(department=dept,range=period(department)){let types=activeTypes(),n=0;for(let day of days(range.start,range.end))for(let t of types)n+=required(department,day,t);return n}function deptName(id=dept){return depts.find(d=>d.id===id)?.name||id}function approved(p,day){return state.requests.some(r=>r.provider===p&&r.status==='Approved'&&day>=r.start&&day<=r.end)}
function interval(a){let t=shiftType(a.shift);if(!t)return [NaN,NaN];let start=date(a.date);start.setHours(...t.start.split(':').map(Number),0,0);let end=date(a.date);end.setHours(...t.end.split(':').map(Number),0,0);if(end<=start)end.setDate(end.getDate()+1);return [+start,+end]}
function violations(a,list=state.assignments){let errors=[],p=provider(a.provider);if(!p)return ['Provider does not exist'];if(!p.affiliations.includes(a.dept))errors.push('Provider is not affiliated with this department');if(!shiftType(a.shift))return ['Unknown shift type'];if(shiftType(a.shift).night&&!p.nights)errors.push('Provider is unavailable for nights');const [s,e]=interval(a);for(let r of state.requests.filter(r=>r.provider===p.id&&r.status==='Approved')){if(s<date(plus(r.end,1)).getTime()&&e>date(r.start).getTime())errors.push('Approved PTO overlaps this shift')}
const others=list.filter(b=>b.id!==a.id&&b.provider===a.provider);for(let b of others){let [bs,be]=interval(b);if(s<be&&e>bs)errors.push('Overlapping assignment · '+deptName(b.dept));else{let gap=s>=be?(s-be)/3600000:(bs-e)/3600000;if(gap<state.rules.rest)errors.push('Minimum '+state.rules.rest+'h rest not met · '+b.date)}}
let rot=rotationFor(a.dept,a.date);if(rot){let n=others.filter(b=>b.date>=rot.start&&b.date<=rot.end).length,mx=p.rotationMax??p.max;if(n>=mx)errors.push('Rotation maximum of '+mx+' shifts exceeded · '+rot.name)}else{let n=others.filter(b=>b.date.slice(0,7)===a.date.slice(0,7)).length;if(n>=p.max)errors.push('Monthly maximum of '+p.max+' shifts exceeded')}let dates=new Set([...others.map(b=>b.date),a.date]),streak=1;for(let i=1;dates.has(plus(a.date,-i));i++)streak++;for(let i=1;dates.has(plus(a.date,i));i++)streak++;if(streak>state.rules.consecutive)errors.push('Maximum '+state.rules.consecutive+' consecutive workdays exceeded');return [...new Set(errors)]}
function validateAll(department=dept,range=period(department)){return relevant(department,range).flatMap(a=>violations(a).map(error=>({a,error})))}function coverageMissing(department=dept,range=period(department)){let gaps=[],have=new Map(),types=activeTypes();for(let a of state.assignments)if(a.dept===department&&a.date>=range.start&&a.date<=range.end){let k=a.date+'|'+a.shift;have.set(k,(have.get(k)||0)+1)}for(let day of days(range.start,range.end))for(let t of types){let need=required(department,day,t);for(let i=have.get(day+'|'+t.id)||0;i<need;i++)gaps.push({date:day,shift:t.id})}return gaps}
function canEdit(dateValue,department=dept){if(isPublished(department,dateValue)){toast('This schedule is published. Reopen it as a draft to edit.');return false}return true}
function addAssignment(a){if(!canEdit(a.date,a.dept))return false;let errs=violations(a);if(errs.length){toast(errs[0]);return false}checkpoint();state.assignments.push(a);commit('Assigned '+provider(a.provider).name+' · '+a.date+' '+a.shift);return true}
function closeSidebar(){document.body.classList.remove('sidebar-open');document.querySelector('#menuToggle').setAttribute('aria-expanded','false')}
function toggleSidebar(){const open=document.body.classList.toggle('sidebar-open');document.querySelector('#menuToggle').setAttribute('aria-expanded',String(open))}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('sidebar-open')){closeSidebar();document.querySelector('#menuToggle').focus()}});
function navigate(v){view=v;closeSidebar();render()}const pages=[['▦','Schedule'],['⟳','Rotations'],['♧','Providers'],['◷','Requests'],['◫','Shift types'],['☷','Rules & coverage'],['▤','Reports'],['↺','Activity'],['⚙','Settings']];
function render(){let pending=state.requests.filter(r=>r.status==='Pending').length;$('#nav').innerHTML=pages.map(([icon,name])=>`<button class="${view===name?'active':''}" onclick="navigate('${name}')"><span>${icon}</span>${name}${name==='Requests'&&pending?`<span class="badge">${pending}</span>`:''}</button>`).join('');$('#breadcrumb').innerHTML='Workspace <b>/</b> '+view;$('#main').innerHTML=({Schedule:schedule,Rotations:rotationsPage,Providers:providersPage,Requests:requestsPage,'Shift types':shiftTypesPage,'Rules & coverage':rulesPage,Reports:reportsPage,Activity:activityPage,Settings:settingsPage}[view])();bindDnD()}
function title(name,sub,actions=''){return `<div class="titlebar"><div><h1>${name}</h1><p class="sub">${sub}</p></div><div class="actions">${actions}</div></div>`}function deptSelect(){return `<select aria-label="Department" onchange="dept=this.value;render()">${depts.map(d=>`<option value="${d.id}" ${d.id===dept?'selected':''}>${d.name}</option>`).join('')}</select>`}
function stats(){let departments=view==='Schedule'?displayDepartments():depts.filter(d=>d.id===dept),rangeFor=d=>view==='Schedule'?visibleRange():period(d.id),slots=departments.reduce((n,d)=>n+totalSlots(d.id,rangeFor(d)),0),gaps=departments.flatMap(d=>coverageMissing(d.id,rangeFor(d))).length,issues=departments.flatMap(d=>validateAll(d.id,rangeFor(d))).length;return `<div class="stats"><div class="stat"><div class="label">Shift coverage <span>◉</span></div><strong>${Math.round((slots?(slots-gaps)/slots*100:100))}<span style="font-size:15px">%</span></strong><small>${slots-gaps} of ${slots} covered</small><div class="bar"><i style="width:${(slots?(slots-gaps)/slots*100:100)}%"></i></div></div><div class="stat"><div class="label">Open shifts <span>☀</span></div><strong>${gaps}</strong><small>need a little attention</small></div><div class="stat"><div class="label">Active providers <span>♧</span></div><strong>${state.providers.filter(p=>departments.some(d=>p.affiliations.includes(d.id))).length}</strong><small>in selected organizations</small></div><div class="stat"><div class="label">Rule conflicts <span>♧</span></div><strong style="color:${issues?'#aa7549':'#518065'}">${issues}</strong><small>${issues?'review before publishing':'looking good'}</small></div></div>`}
function schedule(){if(mode==='Rotation'&&!selectedRotation())mode='Month';let range=visibleRange(),P=period(),R=mode==='Rotation'?selectedRotation():null,mon=R?esc(R.name)+' <small class="muted">'+fmtDate(R.start)+' – '+fmtDate(R.end)+'</small>':cursor.toLocaleString('en-US',{month:'long',year:'numeric'}),gaps=displayDepartments().flatMap(d=>coverageMissing(d.id,range)),issues=displayDepartments().flatMap(d=>validateAll(d.id,range));return title('A schedule everyone can breathe with.','Your team, in balance. Your coverage, taken care of.',`<button onclick="exportCSV()">↗ Export</button><button onclick="generateDialog()" ${locked()?'disabled':''}>✧ Generate ${esc(organizationFor(dept).short)}</button><button class="primary" onclick="publishDialog()">${locked()?'✓ Published':'Publish'} ${esc(organizationFor(dept).short)} ↗</button>`)+stats()+`<div class="toolbar"><div class="filters">${organizationPicker()}<select aria-label="Filter provider" onchange="filter=this.value;render()"><option value="">All providers</option>${state.providers.map(p=>`<option value="${p.id}" ${filter===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="segmented">${(rotationsOf().length?['Rotation','Month','Week']:['Month','Week']).map(v=>`<button class="${mode===v?'selected':''}" onclick="mode='${v}';render()">${v}</button>`).join('')}</div></div><div class="schedule-context"><div class="org-key">${displayOrganizations().map(o=>`<span><i class="dot" style="background:${o.color}"></i>${esc(o.name)}</span>`).join('')}</div><label class="manage-target">Edit / generate / publish for ${deptSelect()}${rotationSelect()}</label></div><div class="calendarwrap"><div class="calhead"><div><h2>${mon}</h2><span class="pill ${locked()?'green':''}">${esc(organizationFor(dept).short)} · ${esc(P.label)} · ${locked()?'Published':'Draft'}</span></div><div><button class="icon" aria-label="Previous period" onclick="changePeriod(-1)">‹</button><button onclick="goToday()" style="font-size:10px;padding:5px 10px">Today</button><button class="icon" aria-label="Next period" onclick="changePeriod(1)">›</button><small>${mode==='Rotation'?'Rotation overview':mode==='Month'?'Monthly overview':'Week of '+iso(cursor)}</small></div></div>${locked()?'<div class="locknote">✓ The editing target’s published schedule is locked. Other organizations retain their own edit status. <a href="#" onclick="reopen();return false">Reopen draft</a> to make changes.</div>':''}<div class="calendar ${mode==='Week'?'week':''}">${calendarCells()}</div><div class="legend"><div>${activeTypes().map(t=>`<span><i class="dot" style="background:${t.color}"></i>${esc(t.name)} · ${shiftRange(t)}</span>`).join('')}</div><span>Drag to move · Click to edit</span></div></div><div class="below"><div class="panel"><div class="panelhead"><div><h3>Your team, ready to go</h3><p style="margin:4px 0 0">Drag a provider onto a date to add a shift.</p></div><button onclick="navigate('Providers')">Manage team ↗</button></div>${state.providers.filter(p=>displayDepartments().some(d=>p.affiliations.includes(d.id))).map(p=>`<div draggable="true" class="providerchip" data-provider="${p.id}"><span class="initials">${initials(p)}</span>${esc(p.name)}</div>`).join('')}<p>Rest and workload checks include both organizations.</p></div><div class="panel"><div class="panelhead"><h3>A little peace of mind</h3><button onclick="navigate('Reports')">View details ↗</button></div><div class="notice ${!gaps.length&&!issues.length?'good':''}">${issues.length?'⚠ '+issues.length+' rule conflicts require review.':gaps.length?'☀ '+gaps.length+' open shifts left to fill. Generate a draft or drag in a provider.':'✓ All required shifts are covered. No rule conflicts detected.'}</div><p>${state.requests.filter(r=>r.status==='Pending').length} time-off requests awaiting review · <a href="#" onclick="navigate('Requests');return false">Review requests</a></p></div></div>`}
function calendarCells(){let R=mode==='Rotation'?selectedRotation():null,start,length;if(R){start=date(R.start);start.setDate(start.getDate()-start.getDay());let last=date(R.end);last.setDate(last.getDate()+6-last.getDay());length=Math.round((last-start)/864e5)+1}else{start=new Date(cursor.getFullYear(),cursor.getMonth(),1);if(mode==='Week')start=new Date(cursor);start.setDate(start.getDate()-start.getDay());length=mode==='Week'?7:Math.ceil((new Date(cursor.getFullYear(),cursor.getMonth(),1).getDay()+daysInMonth())/7)*7}let html=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="dow">${d}</div>`).join('');for(let i=0;i<length;i++){let d=new Date(start);d.setDate(d.getDate()+i);let day=iso(d),out=R?(day<R.start||day>R.end):d.getMonth()!==cursor.getMonth(),holiday=displayDepartments().some(x=>holidayOn(x.id,day)),rs=rotationFor(dept,day);html+=`<div class="day ${out?'out':''} ${[0,6].includes(d.getDay())?'weekend':''} ${holiday?'holiday':''}" data-date="${day}"><div class="date"><button class="add" aria-label="Add assignment ${day}" onclick="assignmentDialog(null,'${day}')">+</button>${rs&&rs.start===day?`<small class="rot-start">${esc(rs.name)}</small>`:''}<span class="${day===iso(new Date())?'today':''}">${d.getDate()}</span></div>${displayDepartments().map(department=>{let org=organizationFor(department.id),h=holidayOn(department.id,day),assign=state.assignments.filter(a=>a.dept===department.id&&a.date===day&&(!filter||a.provider===filter)).sort((a,b)=>minutes(shiftType(a.shift).start)-minutes(shiftType(b.shift).start));return `<section class="org-lane dropzone" data-date="${day}" data-dept="${department.id}" style="--org-color:${org.color}"><div class="org-lane-title"><span class="org-dot"></span>${esc(org.short)}<span class="lane-lock">${isPublished(department.id,day)?'Locked':''}</span></div>${h?`<div class="holiday-tag" title="Holiday · ${esc(org.name)}">✦ ${esc(h.name)}</div>`:''}${assign.map(a=>`<div role="button" tabindex="0" aria-label="Edit ${esc(provider(a.provider)?.name)} ${esc(shiftName(a.shift))} ${day} ${esc(org.name)}" draggable="${!isPublished(a.dept,a.date)}" data-assignment="${a.id}" class="assignment" style="border-color:${shiftType(a.shift)?.color}66;background:${shiftType(a.shift)?.color}18;color:${shiftType(a.shift)?.color}" onclick="assignmentDialog('${a.id}')" onkeydown="if(event.key==='Enter')assignmentDialog('${a.id}')"><span class="shifticon">${shiftType(a.shift)?.night?'☾':'☀'}</span><span>${esc(provider(a.provider)?.name||'Unknown')}<b class="shift-caption">${esc(shiftName(a.shift))} · ${shiftRange(shiftType(a.shift))}</b><b class="assignment-org">${esc(org.short)}</b></span></div>`).join('')}${!out&&!filter?activeTypes().map(t=>{let have=state.assignments.filter(a=>a.dept===department.id&&a.date===day&&a.shift===t.id).length;return Array.from({length:Math.max(0,required(department.id,day,t)-have)},()=>`<div class="assignment open dropzone" role="button" tabindex="0" aria-label="Open ${esc(t.name)} ${esc(org.name)} ${day}" data-date="${day}" data-dept="${department.id}" data-shift="${t.id}" onclick="assignmentDialog(null,'${day}','${t.id}',null,'${department.id}')" onkeydown="if(event.key==='Enter')assignmentDialog(null,'${day}','${t.id}',null,'${department.id}')"><span>${t.night?'☾':'☀'}</span> Open ${esc(t.name)}<small>+</small></div>`).join('')}).join(''):''}</section>`}).join('')}</div>`}return html}
function changePeriod(n){if(mode==='Rotation'){let list=rotationsOf(),i=list.indexOf(selectedRotation())+n;if(list[i]){rotationSel[dept]=list[i].id;cursor=date(list[i].start)}render();return}if(mode==='Week')cursor.setDate(cursor.getDate()+n*7);else cursor=new Date(cursor.getFullYear(),cursor.getMonth()+n,1);render()}
function bindDnD(){document.querySelectorAll('[data-assignment],[data-provider]').forEach(el=>{el.addEventListener('dragstart',e=>{if(el.dataset.assignment){let a=state.assignments.find(a=>a.id===el.dataset.assignment);if(a&&isPublished(a.dept,a.date)){e.preventDefault();return}}e.dataTransfer.setData('text/plain',JSON.stringify(el.dataset.assignment?{id:el.dataset.assignment}:{provider:el.dataset.provider}));e.dataTransfer.effectAllowed='move'})});document.querySelectorAll('.day,.dropzone').forEach(el=>{el.addEventListener('dragover',e=>{e.preventDefault();e.stopPropagation();el.classList.add('dragover')});el.addEventListener('dragleave',()=>el.classList.remove('dragover'));el.addEventListener('drop',e=>{e.preventDefault();e.stopPropagation();document.querySelectorAll('.dragover').forEach(x=>x.classList.remove('dragover'));let payload;try{payload=JSON.parse(e.dataTransfer.getData('text/plain'))}catch{return}if(payload.provider){let target=el.dataset.dept||dept;if(!canEdit(el.dataset.date,target))return;assignmentDialog(null,el.dataset.date,el.dataset.shift||'day',payload.provider,target);return}let old=state.assignments.find(a=>a.id===payload.id);if(!old||!canEdit(old.date,old.dept))return;let updated={...old,date:el.dataset.date,shift:el.dataset.shift||old.shift,dept:el.dataset.dept||old.dept};if(!canEdit(updated.date,updated.dept))return;let errs=violations(updated);if(errs.length){toast('Move blocked: '+errs[0]);return}checkpoint();Object.assign(old,updated);commit('Moved '+provider(old.provider).name+' to '+old.date+' '+old.shift);toast('Assignment moved · Undo is available in Activity')})})}
function modal(html){$('#modal').innerHTML=html;$('#modal').showModal()}function closeModal(){$('#modal').close()}function id(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2)}function assignmentDialog(aid,day,shift='day',pid,targetDept=dept){let a=state.assignments.find(x=>x.id===aid),d=a?.date||day||iso(cursor);targetDept=a?.dept||targetDept;modal(`<h2>${a?'Edit assignment':'Add a shift'}</h2><p>A good schedule starts with the right fit.</p><form onsubmit="saveAssignment(event,'${aid||''}')"><div class="formgrid"><label class="full">Organization / department<select name="department" required onchange="updateAssignmentProviders(this.value)">${depts.map(x=>`<option value="${x.id}" ${x.id===targetDept?'selected':''}>${esc(x.org)} · ${esc(x.name)}</option>`).join('')}</select></label><label class="full">Provider<select name="provider" required>${state.providers.filter(p=>p.affiliations.includes(targetDept)).map(p=>`<option value="${p.id}" ${p.id===(a?.provider||pid)?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Date<input name="date" type="date" value="${d}" required></label><label>Shift type<select name="shift" required>${shiftOptions(a?.shift||shift)}</select></label><label class="full">Notes<textarea name="note" rows="2" maxlength="500">${esc(a?.note||'')}</textarea></label></div><div id="formerror" class="danger" role="alert"></div><div class="modalactions">${a?`<button type="button" class="danger" onclick="deleteAssignment('${a.id}')">Remove shift</button>`:''}<button type="button" onclick="closeModal()">Cancel</button><button class="primary" ${isPublished(targetDept,d)?'disabled':''}>Save assignment</button></div></form>`)}
function saveAssignment(e,aid){e.preventDefault();let f=new FormData(e.target),old=state.assignments.find(a=>a.id===aid),a={id:aid||id(),provider:f.get('provider'),date:f.get('date'),shift:f.get('shift'),dept:f.get('department')||old?.dept||dept,note:f.get('note')};if(old&&!canEdit(old.date,old.dept))return;if(!canEdit(a.date,a.dept))return;let errors=violations(a);if(errors.length){$('#formerror').textContent=errors.join(' · ');return}checkpoint();if(old)Object.assign(old,a);else state.assignments.push(a);closeModal();commit('Saved '+provider(a.provider).name+' · '+a.date+' '+a.shift);toast('Assignment saved')}
function deleteAssignment(aid){let a=state.assignments.find(x=>x.id===aid);if(!canEdit(a.date,a.dept))return;checkpoint();state.assignments=state.assignments.filter(x=>x.id!==aid);closeModal();commit('Removed assignment · '+a.date);toast('Shift removed')}
function generateDialog(){if(locked())return;let P=period();modal(`<h2>Make room for a better ${P.kind==='rotation'?'rotation':'month'}.</h2><p>Fill open shifts in ${esc(P.label)} (${fmtDate(P.start)} – ${fmtDate(P.end)}) for ${esc(deptName())}. Existing assignments stay in place. The generator checks approved PTO, affiliations, global rest, consecutive workdays, and ${P.kind==='rotation'?'rotation':'monthly'} maximums.</p><div class="notice good">Assignments are chosen to balance workload, nights, and weekends. Holiday shifts are filled first and go to providers who covered that holiday least recently. Targets guide selection; maximums are enforced. Unfillable shifts stay open.</div><div class="modalactions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="generate()">✧ Generate draft</button></div>`)}
function generate(silent=false){if(locked())return;checkpoint();let added=0,P=period(),isRot=P.kind==='rotation',gaps=coverageMissing(),hol=g=>holidayOn(dept,g.date);
gaps.sort((a,b)=>(hol(b)?1:0)-(hol(a)?1:0)||a.date.localeCompare(b.date));
for(let gap of gaps){let h=hol(gap),year=+gap.date.slice(0,4);let candidates=state.providers.filter(p=>p.affiliations.includes(dept)).map(p=>{let all=state.assignments.filter(a=>a.provider===p.id&&a.date>=P.start&&a.date<=P.end),nights=all.filter(a=>shiftType(a.shift)?.night).length,weekends=all.filter(a=>[0,6].includes(date(a.date).getDay())).length,target=isRot?(p.rotationTarget??p.target):p.target,score=all.length/Math.max(target,1)*10+(shiftType(gap.shift)?.night?nights*.7:0)+([0,6].includes(date(gap.date).getDay())?weekends*.7:0);
 if(h){let worked=all.filter(isHolidayShift).length,past=holidayHistory(p.id,h.name).filter(y=>y<year),last=past.length?past[past.length-1]:null;score+=worked*4+past.length*2+(last!=null?Math.max(0,4-(year-last))*3:0)}
 return {p,score}}).sort((a,b)=>a.score-b.score||a.p.name.localeCompare(b.p.name));
 for(let {p} of candidates){let a={...gap,id:id(),provider:p.id,dept};if(!violations(a).length){state.assignments.push(a);added++;break}}}
if($('#modal').open)closeModal();commit('Generated '+added+' assignments · '+deptName()+' · '+P.label);if(!silent)toast(added+' shifts filled · '+coverageMissing().length+' remain open')}
function publishDialog(){if(locked()){reopen();return}let gaps=coverageMissing(),issues=validateAll();modal(`<h2>${gaps.length||issues.length?'A few things need attention.':'Ready for the team.'}</h2><p>${gaps.length} open shifts · ${issues.length} rule conflicts. Publishing locks this department’s schedule for ${esc(period().label)} (${fmtDate(period().start)} – ${fmtDate(period().end)}).</p><div class="notice ${gaps.length||issues.length?'':'good'}">${gaps.length||issues.length?'Resolve coverage gaps and rule conflicts before publishing.':'✓ Coverage and configured scheduling rules passed validation.'}</div><div class="modalactions"><button onclick="closeModal()">Back to schedule</button><button class="primary" ${gaps.length||issues.length?'disabled':''} onclick="publish()">Publish schedule</button></div>`)}function publish(){if(coverageMissing().length||validateAll().length)return;checkpoint();let P=period(),snapshot=JSON.parse(JSON.stringify(relevant())),at=new Date().toISOString();if(P.kind==='rotation')Object.assign(P.rotation,{status:'Published',at,snapshot});else state.periods[P.key]={status:'Published',at,snapshot};closeModal();commit('Published '+deptName()+' · '+P.label);toast('Schedule published and locked')}
function reopen(){modal(`<h2>Reopen this schedule?</h2><p>${esc(period().label)} returns to draft. The published snapshot and publication history are kept. Publish again after review.</p><div class="modalactions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="reopenNow()">Reopen draft</button></div>`)}
function reopenNow(){checkpoint();let P=period();if(P.kind==='rotation')P.rotation.status='Draft';else if(state.periods[P.key])state.periods[P.key].status='Draft';closeModal();commit('Reopened schedule · '+P.label)}
function providersPage(){return title('People first. Always.','One provider profile. Every affiliation. A complete view of their commitments.',`<button class="primary" onclick="providerDialog()">+ Add provider</button>`)+`<div class="toolbar">${deptSelect()}<input class="search" placeholder="Search providers…" aria-label="Search providers" oninput="filterProviders(this.value)"></div><div class="tablewrap"><table><thead><tr><th>Provider</th><th>Role</th><th>Affiliations</th><th>Rotation target / max</th><th>Night shifts</th><th></th></tr></thead><tbody>${state.providers.map(p=>`<tr data-name="${esc(p.name.toLowerCase())}"><td><div class="namecell"><span class="avatar">${initials(p)}</span><strong>${esc(p.name)}</strong></div></td><td>${esc(p.role)}</td><td>${p.affiliations.map(d=>esc(deptName(d))).join('<br>')}</td><td>${p.rotationTarget} / ${p.rotationMax}<br><small class="muted">Monthly, outside rotations: ${p.target} / ${p.max}</small></td><td>${p.nights?'Available':'Days only'}</td><td><button onclick="providerDialog('${p.id}')">Edit</button></td></tr>`).join('')}</tbody></table></div><div class="notice good" style="margin-top:20px">Shared providers use a single profile. All assignments across both organizations count toward rest and maximum checks. A rotation maximum counts every shift the provider works during the dates of that team’s rotation.</div>`}
function filterProviders(v){document.querySelectorAll('tr[data-name]').forEach(tr=>tr.hidden=!tr.dataset.name.includes(v.toLowerCase()))}
function providerDialog(pid){let p=provider(pid);modal(`<h2>${p?'Edit provider':'Meet your newest teammate.'}</h2><p>Affiliations define where this provider can be assigned.</p><form onsubmit="saveProvider(event,'${pid||''}')"><div class="formgrid"><label class="full">Full name<input name="name" value="${esc(p?.name||'')}" required maxlength="60"></label><label>Role<input name="role" value="${esc(p?.role||'CNM')}" required maxlength="30"></label><label>Night availability<select name="nights"><option value="yes">Available for nights</option><option value="no" ${p&&!p.nights?'selected':''}>Day shifts only</option></select></label><label>Rotation target (shifts)<input type="number" name="rotationTarget" value="${p?.rotationTarget??20}" min="0" max="400" required></label><label>Rotation maximum (shifts)<input type="number" name="rotationMax" value="${p?.rotationMax??28}" min="1" max="400" required></label><label>Monthly target · outside rotations<input type="number" name="target" value="${p?.target??10}" min="0" max="62" required></label><label>Monthly maximum · outside rotations<input type="number" name="max" value="${p?.max??14}" min="1" max="62" required></label><div class="full">${depts.map(d=>`<label class="check"><input type="checkbox" name="affiliation" value="${d.id}" ${(p?.affiliations||[dept]).includes(d.id)?'checked':''}>${esc(d.name)}</label>`).join('')}</div></div><div id="formerror" class="danger"></div><div class="modalactions"><button type="button" onclick="closeModal()">Cancel</button><button class="primary">Save provider</button></div></form>`)}
function saveProvider(e,pid){e.preventDefault();let f=new FormData(e.target),p={id:pid||id(),name:f.get('name').trim(),role:f.get('role').trim(),nights:f.get('nights')==='yes',target:+f.get('target'),max:+f.get('max'),rotationTarget:+f.get('rotationTarget'),rotationMax:+f.get('rotationMax'),affiliations:f.getAll('affiliation')};if(!p.name||!p.affiliations.length||p.target>p.max||p.rotationTarget>p.rotationMax){$('#formerror').textContent='Enter a name, choose an affiliation, and keep each target at or below its maximum.';return}let old=provider(pid);if(old){let backup={...old};Object.assign(old,p);if(state.assignments.some(a=>a.provider===pid&&isPublished(a.dept,a.date)&&violations(a).length)){Object.assign(old,backup);$('#formerror').textContent='This change would conflict with a published schedule. Reopen the affected schedule first.';return}Object.assign(old,backup)}checkpoint();if(old)Object.assign(old,p);else state.providers.push(p);closeModal();commit('Saved provider · '+p.name);toast('Provider saved')}
function requestsPage(){return title('Time off, without the back-and-forth.','Review availability before it becomes a scheduling conflict.',`<button class="primary" onclick="requestDialog()">+ New request</button>`)+`<div class="tablewrap"><table><thead><tr><th>Provider</th><th>Dates</th><th>Reason</th><th>Status</th><th>Review</th></tr></thead><tbody>${state.requests.map(r=>`<tr><td><strong>${esc(provider(r.provider)?.name)}</strong></td><td>${r.start} → ${r.end}</td><td>${esc(r.reason)}</td><td><span class="pill ${r.status==='Approved'?'green':''}">${r.status}</span></td><td>${r.status==='Pending'?`<button onclick="reviewRequest('${r.id}','Approved')">Approve</button> <button onclick="reviewRequest('${r.id}','Declined')">Decline</button>`:`<button onclick="reviewRequest('${r.id}','Pending')">Reopen</button>`}</td></tr>`).join('')||'<tr><td colspan="5">No requests yet.</td></tr>'}</tbody></table></div><div class="panel" style="margin-top:20px"><h3>Availability is global.</h3><p>Approved PTO blocks overlapping shifts in every department. If an approval conflicts with existing assignments, resolve those assignments first.</p></div>`}
function requestDialog(){modal(`<h2>A little time away.</h2><p>Submit time off for scheduler review.</p><form onsubmit="saveRequest(event)"><label>Provider<select name="provider">${state.providers.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><div class="formgrid"><label>First day<input name="start" type="date" value="${iso(cursor)}" required></label><label>Last day<input name="end" type="date" value="${iso(cursor)}" required></label></div><label>Reason (optional)<input name="reason" maxlength="160"></label><div id="formerror" class="danger"></div><div class="modalactions"><button type="button" onclick="closeModal()">Cancel</button><button class="primary">Submit request</button></div></form>`)}
function saveRequest(e){e.preventDefault();let f=new FormData(e.target),r=Object.fromEntries(f);if(r.end<r.start){$('#formerror').textContent='End date must be on or after the first day.';return}checkpoint();state.requests.push({...r,id:id(),status:'Pending'});closeModal();commit('Requested PTO · '+provider(r.provider).name+' · '+r.start);toast('Request submitted')}
function reviewRequest(rid,status){let r=state.requests.find(x=>x.id===rid);if(status==='Approved'){let start=date(r.start).getTime(),end=date(plus(r.end,1)).getTime();let conflicts=state.assignments.filter(a=>{let [s,e]=interval(a);return a.provider===r.provider&&s<end&&e>start});if(conflicts.length){toast('Approval blocked: '+conflicts.length+' assignments overlap this PTO. Move or remove them first.');return}}if(r.status==='Approved'&&status!=='Approved'&&state.assignments.some(a=>a.provider===r.provider&&state.periods[a.dept+':'+a.date.slice(0,7)]?.status==='Published')){/* Removing a block cannot invalidate assignments. */}checkpoint();r.status=status;commit(status+' PTO · '+provider(r.provider).name);toast('Request '+status.toLowerCase())}
function rulesPage(){return title('The rules behind the balance.','Clear guardrails. Consistent decisions. No mystery math.')+`<div class="notice good" style="margin-bottom:18px">Shift hours and required coverage are now configured in <a href="#" onclick="navigate('Shift types');return false">Shift types</a>.</div><form onsubmit="saveRules(event)" class="panel"><div class="panelhead"><div><h3>Scheduling guardrails</h3><p>Applies across this pilot workspace. Provider-specific maximums are managed in Providers.</p></div><span class="pill green">Hard constraints</span></div>${[['rest','Minimum rest between shifts','Hours off between any two assignments, across organizations.',0,72],['consecutive','Maximum consecutive workdays','Counts consecutive dates worked across all departments.',1,14],].map(([key,name,desc,min,max])=>`<div class="rule"><div><strong>${name}</strong><p>${desc}</p></div><input aria-label="${name}" type="number" name="${key}" value="${state.rules[key]}" min="${min}" max="${max}" required></div>`).join('')}<div class="rule"><div><strong>No overlapping assignments</strong><p>A provider can only be in one place at a time.</p></div><span class="pill green">Always enforced</span></div><div class="rule"><div><strong>Approved PTO & department affiliation</strong><p>Eligibility and availability are checked on every assignment.</p></div><span class="pill green">Always enforced</span></div><div style="margin-top:20px;text-align:right"><button class="primary">Save rules</button></div></form><div class="below"><div class="panel"><h3>Soft goals</h3><p>The generator prioritizes providers with the lowest workload relative to their rotation target (monthly target outside rotations), then balances night and weekend counts. Holiday shifts go to providers who covered that holiday least recently. Existing assignments stay in place.</p></div><div class="panel"><h3>Exceptions need their own workflow.</h3><p>This pilot blocks hard-rule violations. Approval-based rule exceptions, affiliation-specific contracts, and credential expiration are not yet implemented.</p></div></div>`}
function saveRules(e){e.preventDefault();let next=Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,+v])),old=state.rules;state.rules=next;let bad=state.assignments.some(a=>isPublished(a.dept,a.date)&&violations(a).length);state.rules=old;if(bad){toast('Reopen published schedules before changing rules that affect them.');return}checkpoint();state.rules=next;commit('Updated workspace scheduling rules');toast('Rules saved · Draft conflicts updated')}
function reportsPage(){let P=period(),isRot=P.kind==='rotation',rows=state.providers.map(p=>{let a=state.assignments.filter(a=>a.provider===p.id&&a.date>=P.start&&a.date<=P.end);return {p,total:a.length,hours:a.reduce((n,x)=>n+shiftHours(x.shift),0),night:a.filter(a=>shiftType(a.shift)?.night).length,weekend:a.filter(a=>[0,6].includes(date(a.date).getDay())).length,holiday:a.filter(isHolidayShift).length,max:isRot?p.rotationMax:p.max,target:isRot?p.rotationTarget:p.target}});return title('A fairer picture.',(isRot?'Rotation':'Monthly')+' workload across every affiliation. '+esc(P.label)+' · '+fmtDate(P.start)+' – '+fmtDate(P.end),'<button onclick="exportCSV()">↗ Export assignments</button>')+`<div class="toolbar">${deptSelect()}${rotationSelect()}<div><button onclick="changePeriod(-1)">‹ Previous</button> <button onclick="changePeriod(1)">Next ›</button></div></div>`+stats()+`<div class="tablewrap"><table><thead><tr><th>Provider</th><th>Total shifts</th><th>Nights</th><th>Weekend shifts</th><th>Holiday shifts</th><th>Hours</th><th>Target progress</th></tr></thead><tbody>${rows.map(({p,total,night,weekend,holiday,hours,max,target})=>`<tr><td><strong>${esc(p.name)}</strong></td><td>${total} / ${max} max</td><td>${night}</td><td>${weekend}</td><td>${holiday}</td><td>${hours}</td><td><span class="progress"><i style="width:${Math.min(100,total/Math.max(1,target)*100)}%"></i></span> ${total}/${target}</td></tr>`).join('')}</tbody></table></div><div class="below"><div class="panel"><h3>Coverage gaps · ${coverageMissing().length}</h3><p>${coverageMissing().slice(0,12).map(g=>g.date+' · '+esc(shiftName(g.shift))+(holidayOn(dept,g.date)?' · '+esc(holidayOn(dept,g.date).name):'')).join('<br>')||'Every required shift is covered.'}${coverageMissing().length>12?'<br>… and more':''}</p></div><div class="panel"><h3>Rule validation · ${validateAll().length}</h3><p>${validateAll().map(v=>`${v.a.date} · ${esc(provider(v.a.provider).name)} · ${esc(v.error)}`).join('<br>')||'No configured hard-rule conflicts found.'}</p></div></div>${holidayReport()}`}
function activityPage(){return title('Every change has a story.','Assignment changes, approvals, and published schedules in one place.',`<button onclick="undo()" ${!history.length?'disabled':''}>↶ Undo last change</button>`)+`<div class="panel">${state.audit.slice(0,80).map(a=>`<div class="audit"><span class="initials">JL</span><div>${esc(a.text)}<small>${new Date(a.time).toLocaleString()} · ${a.by?esc(a.by):CLOUD?'Workspace':'Local workspace'}</small></div></div>`).join('')||'<div class="empty">Your workspace activity will appear here.</div>'}</div>`}
function undo(){if(!history.length)return;state=migrate(JSON.parse(history.pop()));audit('Undid last change');persist();render();toast('Last change undone')}
function settingsPage(){return title('Your scheduling home.','A calm workspace for complicated schedules.')+`<div class="below"><div class="panel"><h3>Workspace</h3><p>Vanderbilt Midwives · Inpatient OB</p><table><tr><td>Scheduling format</td><td>Configurable shift types · 24/7</td></tr><tr><td>Organizations</td><td>Jones Team<br>Boehm Team</td></tr><tr><td>Current role</td><td>${CLOUD?esc(CLOUD.roleLabel()):'Administrator pilot'}</td></tr><tr><td>Call shifts</td><td>Outside V1 scope</td></tr></table></div><div class="panel"><h3>Your data, within reach.</h3><p>${CLOUD?'Changes save to the shared workspace after the server checks every scheduling rule. Download a JSON backup any time.':'This interactive pilot saves automatically in this browser. Download a JSON backup to transfer or preserve your workspace.'}</p><button onclick="backup()">Download backup</button> <button onclick="$('#importFile').click()">Restore backup</button><input type="file" accept="application/json" id="importFile" hidden onchange="restore(event)"><p>${CLOUD?'Restoring replaces the shared workspace for everyone (administrators only). A rollback snapshot is taken first.':'Restoring replaces this browser’s current workspace.'}</p>${CLOUD?'':'<button class="danger" onclick="resetDialog()">Reset sample workspace</button>'}</div></div>${CLOUD?CLOUD.settingsPanels():''}<div class="panel" style="margin-top:20px"><h3>What this pilot includes</h3><p>Interactive calendar, drag-and-drop assignments and provider cards, deterministic schedule generation, global conflicts, provider editing, PTO review, configurable rules, workload reporting, publish locks, undo, CSV exports, and backups.</p><h3 style="margin-top:20px">Before a real clinical rollout</h3><p>${CLOUD?'Shared storage, sign-in, workspace roles, server-side rule checks, and append-only history are in place. Still to come: ':'Shared server storage, authenticated user roles, organization-level data permissions, secure audit retention, '}notifications, shift swaps, credential validation, affiliation-specific rules, and operational reliability testing still need implementation. ${CLOUD?'Confirm schedules against your department’s own policies before relying on them for staffing.':'Use sample data here; this is not a production clinical scheduling system.'}</p></div>`}
function download(text,name,type){let url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function csvCell(s){let v=String(s??'');if(/^[=+@\-]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"'}function exportCSV(){let range=view==='Schedule'?visibleRange():null,list=view==='Schedule'?displayDepartments().flatMap(d=>relevant(d.id,range)):relevant(),rows=[['Date','Shift','Department','Organization','Provider','Start','End','Holiday','Notes'],...list.sort((a,b)=>a.date.localeCompare(b.date)||a.shift.localeCompare(b.shift)).map(a=>[a.date,shiftName(a.shift),deptName(a.dept),depts.find(d=>d.id===a.dept).org,provider(a.provider)?.name,shiftType(a.shift).start,(minutes(shiftType(a.shift).end)<=minutes(shiftType(a.shift).start)?plus(a.date,1):a.date)+' '+shiftType(a.shift).end,holidayOn(a.dept,a.date)?.name||'',a.note||''])],r=range||period();download(rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'CountSchedula-'+r.start+'_to_'+r.end+'.csv','text/csv')}
function backup(){download(JSON.stringify(state,null,2),'CountSchedula-backup.json','application/json')}
async function restore(e){try{let data=JSON.parse(await e.target.files[0].text());if(!Array.isArray(data.providers)||!Array.isArray(data.assignments)||!Array.isArray(data.requests)||!Array.isArray(data.audit)||!data.periods||!data.rules)throw Error();data=migrate(data);validateShiftTypes(data.shiftTypes);let ids=new Set();if(data.providers.length>1000||data.assignments.length>100000||data.requests.length>20000)throw Error();for(let p of data.providers){if(typeof p.id!=='string'||!SAFE_ID.test(p.id)||!p.name.trim()||p.name.length>120||p.role.length>60||(p.nights!==undefined&&typeof p.nights!=='boolean')||ids.has(p.id)||typeof p.name!=='string'||typeof p.role!=='string'||!Array.isArray(p.affiliations)||p.affiliations.some(d=>!depts.some(x=>x.id===d))||!Number.isFinite(p.max)||!Number.isFinite(p.target)||p.max<1||p.target<0||p.target>p.max||!Number.isFinite(p.rotationMax)||!Number.isFinite(p.rotationTarget)||p.rotationMax<1||p.rotationTarget<0||p.rotationTarget>p.rotationMax)throw Error();ids.add(p.id)}let aids=new Set();for(let a of data.assignments){if(typeof a.id!=='string'||!SAFE_ID.test(a.id)||aids.has(a.id)||(a.note!=null&&(typeof a.note!=='string'||a.note.length>500))||!/^\d{4}-\d{2}-\d{2}$/.test(a.date)||iso(date(a.date))!==a.date||!ids.has(a.provider)||!data.shiftTypes.some(t=>t.id===a.shift)||!depts.some(d=>d.id===a.dept))throw Error();aids.add(a.id)}let rids=new Set();for(let r of data.requests){if(typeof r.id!=='string'||!SAFE_ID.test(r.id)||rids.has(r.id)||!ids.has(r.provider)||![r.start,r.end].every(d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)&&iso(date(d))===d)||r.end<r.start||!['Pending','Approved','Declined'].includes(r.status)||(r.reason!=null&&(typeof r.reason!=='string'||r.reason.length>160)))throw Error();rids.add(r.id)}for(let [k,v] of Object.entries(data.periods)){if(!/^[A-Za-z0-9_-]{1,64}:\d{4}-(0[1-9]|1[0-2])$/.test(k)||!depts.some(d=>d.id===k.split(':')[0])||!v||!['Draft','Published'].includes(v.status))throw Error()}if(!data.audit.every(x=>x&&typeof x.text==='string'))throw Error();for(let key of ['rest','consecutive'])if(!Number.isFinite(data.rules[key])||data.rules[key]<0)throw Error();if(data.rules.rest>72||data.rules.consecutive<1||data.rules.consecutive>14)throw Error();validateRotations(data.rotations);validateRotationDefaults(data.rotationDefaults);validateHolidayHistory(data.holidayHistory,ids);if(CLOUD)return CLOUD.confirmImport(data);checkpoint();state=data;commit('Restored workspace backup');toast('Backup restored')}catch{toast('Could not restore: the file is not a valid CountSchedula backup.')}}
function resetDialog(){modal(`<h2>Start fresh?</h2><p>This replaces all local providers, requests, and schedules with sample data. Download a backup first if you want to keep your work.</p><div class="modalactions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="checkpoint();state=migrate(seed());generate(true);closeModal();render();toast('Sample workspace reset')">Reset workspace</button></div>`)}
function help(){modal(`<h2>A little scheduling help.</h2><p><strong>Move an assignment:</strong> drag a shift card to a new date, or onto an open shift slot to change its shift.<br><br><strong>Add a shift:</strong> drag a provider from the team tray to the calendar, click an open slot, or use a date’s + button.<br><br><strong>Keep it safe:</strong> blocked moves explain the conflicting rule. Published schedules must be reopened before editing.<br><br><strong>Keyboard:</strong> Tab to a shift and press Enter to edit its date, provider, or shift. Changes can be undone in Activity.<br><br>All sample shift times use the same local time zone. Cross-time-zone scheduling is not implemented.</p><div class="modalactions"><button class="primary" onclick="closeModal()">Got it</button></div>`)}
function validateShiftTypes(types){if(!Array.isArray(types)||!types.length)throw Error('At least one shift type is required');let ids=new Set(),names=new Set();for(let t of types){if(!/^[a-z0-9-]+$/.test(t.id)||ids.has(t.id)||typeof t.name!=='string'||!t.name.trim()||t.name.length>40||names.has(t.name.trim().toLowerCase())||!/^([01]\d|2[0-3]):[0-5]\d$/.test(t.start)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(t.end)||t.start===t.end||!/^#[a-f0-9]{6}$/i.test(t.color)||!Number.isInteger(t.coverage)||t.coverage<0||t.coverage>10||typeof t.active!=='boolean'||typeof t.night!=='boolean')throw Error('Check shift names, hours, color, and required coverage (0–10). Names must be unique and start/end times must differ.');ids.add(t.id);names.add(t.name.trim().toLowerCase())}if(!types.some(t=>t.active))throw Error('Keep at least one shift type active')}
function shiftTypesPage(){return title('Every kind of shift. One schedule.','Configure the hours, color, and daily coverage for each shift type.',`<button class="primary" onclick="shiftTypeDialog()">+ Add shift type</button>`)+`<div class="notice good" style="margin-bottom:18px">Day and Night retain their existing assignments. The four additional sample types start with 0 required providers per day—available for manual assignments. Raise coverage to include them in open shifts and automatic generation.</div><div class="tablewrap"><table><thead><tr><th>Shift type</th><th>Hours</th><th>Duration</th><th>Required / day</th><th>Night category</th><th>Status</th><th></th></tr></thead><tbody>${state.shiftTypes.map(t=>`<tr><td><span class="dot" style="background:${t.color}"></span><strong>${esc(t.name)}</strong></td><td>${shiftRange(t)}${minutes(t.end)<minutes(t.start)?' <small class="muted">(+1 day)</small>':''}</td><td>${shiftHours(t.id)}h</td><td>${t.coverage}${t.coverage===0?' · Optional':''}</td><td>${t.night?'Yes':'No'}</td><td><span class="pill ${t.active?'green':''}">${t.active?'Active':'Inactive'}</span></td><td><button onclick="shiftTypeDialog('${t.id}')">Edit</button></td></tr>`).join('')}</tbody></table></div><div class="below"><div class="panel"><h3>Coverage drives the calendar.</h3><p>Required providers are counted per day, for each department. A value of 0 makes a shift optional. Active types appear in assignment editors and the calendar legend.</p></div><div class="panel"><h3>Hours drive conflict checks.</h3><p>Overnight shifts end the following day. Overlap, rest, PTO, exports, and reported hours use each type’s configured times. Night-category shifts follow provider night availability.</p></div></div>`}
function shiftTypeDialog(tid){let t=shiftType(tid);modal(`<h2>${t?'Edit shift type':'Add a shift type'}</h2><p>Changes apply across this workspace. Required coverage applies every day to both departments.</p><form onsubmit="saveShiftType(event,'${tid||''}')"><div class="formgrid"><label class="full">Name<input name="name" required maxlength="40" value="${esc(t?.name||'')}"></label><label>Start time<input type="time" name="start" required value="${t?.start||'07:00'}"></label><label>End time<input type="time" name="end" required value="${t?.end||'19:00'}"></label><label>Required providers per day<input type="number" name="coverage" min="0" max="10" step="1" required value="${t?.coverage??0}"></label><label>Calendar color<input type="color" name="color" value="${t?.color||'#6b9b69'}"></label><label class="check"><input type="checkbox" name="night" ${t?.night?'checked':''}>Night category</label><label class="check"><input type="checkbox" name="active" ${!t||t.active?'checked':''}>Active</label></div><p>End times earlier than start times finish the next day. Deactivate a type to stop new assignments while retaining history.</p><div id="formerror" class="danger" role="alert"></div><div class="modalactions"><button type="button" onclick="closeModal()">Cancel</button><button class="primary">Save shift type</button></div></form>`)}
function saveShiftType(e,tid){e.preventDefault();let f=new FormData(e.target),t={id:tid||'shift-'+id().replaceAll('-',''),name:f.get('name').trim(),start:f.get('start'),end:f.get('end'),color:f.get('color'),coverage:+f.get('coverage'),night:f.has('night'),active:f.has('active')},old=shiftType(tid),next=state.shiftTypes.map(x=>x.id===tid?t:x);if(!old)next.push(t);try{validateShiftTypes(next)}catch(err){$('#formerror').textContent=err.message;return}let published=anyPublished(),referenced=state.assignments.some(a=>a.shift===tid&&isPublished(a.dept,a.date));if((published&&((old?.active?old.coverage:0)!==(t.active?t.coverage:0)))||(referenced&&(t.start!==old.start||t.end!==old.end||t.night!==old.night))){$('#formerror').textContent='Reopen affected published schedules before changing required coverage or assigned shift hours/category.';return}checkpoint();state.shiftTypes=next;closeModal();commit('Saved shift type · '+t.name);toast('Shift type saved · Calendar and coverage updated')}

const organizations=[...new Set(depts.map(d=>d.org))].map((name,i)=>({id:depts.find(d=>d.org===name).id,name,short:name,color:['#377862','#527ca8','#a0744a'][i%3]}));
function organizationFor(department){return organizations.find(o=>o.name===depts.find(d=>d.id===department)?.org)||organizations[0]}
function displayOrganizations(){return organizations.filter(o=>selectedOrgs.includes(o.id))}
function displayDepartments(){return depts.filter(d=>displayOrganizations().some(o=>o.name===d.org))}
function isPublished(department,day){return state.periods[department+':'+day.slice(0,7)]?.status==='Published'||rotationFor(department,day)?.status==='Published'}
function organizationPicker(){return `<details class="org-picker"><summary aria-label="Display organizations">${selectedOrgs.length===1?esc(displayOrganizations()[0].name):selectedOrgs.length+' organizations'} <span>⌄</span></summary><div class="org-picker-menu"><strong>Display organizations</strong>${organizations.map(o=>`<label class="check"><input type="checkbox" value="${o.id}" ${selectedOrgs.includes(o.id)?'checked':''} onchange="toggleOrganization(this.value,this.checked,this)"><i class="dot" style="background:${o.color}"></i>${esc(o.name)}</label>`).join('')}<button onclick="selectedOrgs=organizations.map(o=>o.id);render()">Select all</button><p>Choose one or more organizations.</p></div></details>`}
function toggleOrganization(id,checked,input){if(!checked&&selectedOrgs.length===1){input.checked=true;toast('Keep at least one organization selected.');return}selectedOrgs=checked?[...new Set([...selectedOrgs,id])]:selectedOrgs.filter(x=>x!==id);render();let picker=$('.org-picker');if(picker)picker.open=true}
function updateAssignmentProviders(department){let select=$('#modal select[name="provider"]'),old=select.value;select.innerHTML=state.providers.filter(p=>p.affiliations.includes(department)).map(p=>`<option value="${p.id}" ${p.id===old?'selected':''}>${esc(p.name)}</option>`).join('');let day=$('#modal input[name="date"]').value;$('#modal button.primary').disabled=isPublished(department,day)}
document.addEventListener('click',e=>{let picker=$('.org-picker');if(picker&&e.target.isConnected&&!picker.contains(e.target))picker.open=false});
// ---------------------------------------------------------------- Rotations
// A rotation is a team's scheduling period (default 8 weeks). It replaces the calendar month as the
// unit that is generated, published, locked and reopened. Teams (departments) have their own rotations.
// Dates outside every rotation fall back to the original calendar-month behavior and monthly limits.
const ROTATION_UNITS=['days','weeks','months'];
function validDate(s){return typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&iso(date(s))===s}
function days(start,end){let out=[];for(let d=start;d<=end;d=plus(d,1))out.push(d);return out}
function fmtDate(s){return date(s).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}
function rotationsOf(department=dept){return (state.rotations||[]).filter(r=>r.dept===department).sort((a,b)=>a.start.localeCompare(b.start))}
function rotationFor(department,day){return (state.rotations||[]).find(r=>r.dept===department&&day>=r.start&&day<=r.end)}
function rotationById(rid){return (state.rotations||[]).find(r=>r.id===rid)}
// The rotation the editing target works on: the one chosen in the schedule toolbar, otherwise the one
// containing the calendar cursor, otherwise the next upcoming (or the last) rotation.
function selectedRotation(department=dept){let list=rotationsOf(department);if(!list.length)return null;let sel=rotationSel[department];if(sel==='')return null;if(sel){let r=list.find(r=>r.id===sel);if(r)return r}let day=iso(cursor);return rotationFor(department,day)||list.find(r=>r.start>=day)||list[list.length-1]}
function period(department=dept){let r=selectedRotation(department);if(r)return {kind:'rotation',rotation:r,dept:department,start:r.start,end:r.end,label:r.name,key:'rotation:'+r.id};let y=cursor.getFullYear(),m=cursor.getMonth();return {kind:'month',dept:department,start:iso(new Date(y,m,1)),end:iso(new Date(y,m+1,0)),label:cursor.toLocaleString('en-US',{month:'long',year:'numeric'}),key:department+':'+monthKey()}}
function periodStatus(p=period()){return p.kind==='rotation'?p.rotation.status:state.periods[p.key]?.status||'Draft'}
function anyPublished(){return Object.values(state.periods).some(p=>p.status==='Published')||(state.rotations||[]).some(r=>r.status==='Published')}
function visibleRange(){if(mode==='Rotation'){let r=selectedRotation();if(r)return {start:r.start,end:r.end}}if(mode==='Week'){let s=new Date(cursor);s.setDate(s.getDate()-s.getDay());return {start:iso(s),end:plus(iso(s),6)}}let y=cursor.getFullYear(),m=cursor.getMonth();return {start:iso(new Date(y,m,1)),end:iso(new Date(y,m+1,0))}}
function defaultMode(){return rotationsOf(dept).length?'Rotation':'Month'}
// Inclusive end date of a rotation that starts on `start` and lasts length × unit.
function addDuration(start,length,unit){let d=date(start);if(unit==='days')d.setDate(d.getDate()+length);else if(unit==='weeks')d.setDate(d.getDate()+7*length);else{let day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+length);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()))}return plus(iso(d),-1)}
function rotationLength(r){let n=Math.round((date(r.end)-date(r.start))/864e5)+1;return n%7===0?(n/7)+(n===7?' week':' weeks'):n+(n===1?' day':' days')}

// ---------------------------------------------------------------- Holidays
function holidayOn(department,day){return rotationFor(department,day)?.holidays?.find(h=>h.date===day)}
function holidayKey(name){return String(name||'').trim().toLowerCase().replace(/\s+/g,' ')}
function isHolidayShift(a){return !!holidayOn(a.dept,a.date)}
// Required providers for a shift type on a day: a holiday's override, otherwise the type's daily coverage.
function required(department,day,t){if(!t.active)return 0;let h=holidayOn(department,day);return h&&h.coverage&&Number.isInteger(h.coverage[t.id])?h.coverage[t.id]:t.coverage}
// Years a provider covered a named holiday: assignments on that holiday plus recorded past coverage.
function holidayHistory(pid,name){let key=holidayKey(name),years=new Set();for(let a of state.assignments){if(a.provider!==pid)continue;let h=holidayOn(a.dept,a.date);if(h&&holidayKey(h.name)===key)years.add(+a.date.slice(0,4))}for(let x of state.holidayHistory||[])if(x.provider===pid&&holidayKey(x.holiday)===key)years.add(+x.year);return [...years].sort((a,b)=>a-b)}
function holidayNames(){let m=new Map();for(let r of state.rotations||[])for(let h of r.holidays||[])if(!m.has(holidayKey(h.name)))m.set(holidayKey(h.name),{name:h.name,md:h.date.slice(5)});for(let x of state.holidayHistory||[])if(!m.has(holidayKey(x.holiday)))m.set(holidayKey(x.holiday),{name:x.holiday,md:'99'});return [...m.values()].sort((a,b)=>a.md.localeCompare(b.md)||a.name.localeCompare(b.name)).map(x=>x.name)}
function standardHolidays(year){let nth=(m,wd,n)=>{let d=new Date(year,m,1),c=0;for(;;){if(d.getDay()===wd&&++c===n)return iso(d);d.setDate(d.getDate()+1)}},last=(m,wd)=>{let d=new Date(year,m+1,0);while(d.getDay()!==wd)d.setDate(d.getDate()-1);return iso(d)};return [["New Year's Day",`${year}-01-01`],['Memorial Day',last(4,1)],['Independence Day',`${year}-07-04`],['Labor Day',nth(8,1,1)],['Thanksgiving Day',nth(10,4,4)],['Christmas Eve',`${year}-12-24`],['Christmas Day',`${year}-12-25`],["New Year's Eve",`${year}-12-31`]]}
function standardHolidaysBetween(start,end){let out=[];for(let y=+start.slice(0,4);y<=+end.slice(0,4);y++)for(let [name,d] of standardHolidays(y))if(d>=start&&d<=end)out.push({name,date:d});return out}

// ---------------------------------------------------------------- Validation (also used by restore)
function validateRotations(list){
 if(!Array.isArray(list)||list.length>2000)throw Error('Rotations must be a list');
 let ids=new Set();
 for(let r of list){
  if(!r||typeof r.id!=='string'||!SAFE_ID.test(r.id)||ids.has(r.id))throw Error('Each rotation needs a unique ID');ids.add(r.id);
  if(!depts.some(d=>d.id===r.dept))throw Error('Unknown team for a rotation');
  if(typeof r.name!=='string'||!r.name.trim()||r.name.length>60)throw Error('Rotation names must be 1–60 characters');
  if(!validDate(r.start)||!validDate(r.end)||r.end<r.start)throw Error(r.name+': the end date must be on or after the start date');
  if((date(r.end)-date(r.start))/864e5>366)throw Error(r.name+': a rotation can be at most one year long');
  if(!['Draft','Published'].includes(r.status))throw Error(r.name+': invalid status');
  if(!Array.isArray(r.holidays)||r.holidays.length>60)throw Error(r.name+': invalid holidays');
  let hd=new Set(),hid=new Set();
  for(let h of r.holidays){
   if(!h||typeof h.id!=='string'||!SAFE_ID.test(h.id)||hid.has(h.id))throw Error(r.name+': each holiday needs a unique ID');hid.add(h.id);
   if(typeof h.name!=='string'||!h.name.trim()||h.name.length>60)throw Error(r.name+': holiday names must be 1–60 characters');
   if(!validDate(h.date)||h.date<r.start||h.date>r.end)throw Error(r.name+': '+h.name+' must fall within the rotation dates');
   if(hd.has(h.date))throw Error(r.name+': only one holiday per date');hd.add(h.date);
   if(h.coverage!=null&&(typeof h.coverage!=='object'||Array.isArray(h.coverage)||Object.entries(h.coverage).some(([k,v])=>!/^[a-z0-9-]{1,64}$/.test(k)||!Number.isInteger(v)||v<0||v>10)))throw Error(r.name+': holiday coverage must be whole numbers from 0 to 10')
  }
 }
 for(let d of depts){let rs=list.filter(r=>r.dept===d.id).sort((a,b)=>a.start.localeCompare(b.start));for(let i=1;i<rs.length;i++)if(rs[i].start<=rs[i-1].end)throw Error(rs[i-1].name+' and '+rs[i].name+' overlap for '+d.org)}
}
function validateRotationDefaults(obj){if(!obj||typeof obj!=='object'||Array.isArray(obj))throw Error('Invalid rotation defaults');for(let [k,v] of Object.entries(obj)){if(!depts.some(d=>d.id===k)||!v||typeof v!=='object')throw Error('Invalid rotation defaults');if(v.start!=null&&v.start!==''&&!validDate(v.start))throw Error('Default start date is not a real date');if(!Number.isInteger(v.length)||v.length<1||v.length>366||!ROTATION_UNITS.includes(v.unit))throw Error('Rotation length must be 1–366 days, weeks, or months')}}
function validateHolidayHistory(list,providerIds){if(!Array.isArray(list)||list.length>5000)throw Error('Invalid holiday history');let ids=new Set();for(let x of list){if(!x||typeof x.id!=='string'||!SAFE_ID.test(x.id)||ids.has(x.id)||!providerIds.has(x.provider)||typeof x.holiday!=='string'||!x.holiday.trim()||x.holiday.length>60||!Number.isInteger(x.year)||x.year<1990||x.year>2100)throw Error('Invalid holiday history entry');ids.add(x.id)}}

// ---------------------------------------------------------------- Rotation actions
function rotationSelect(){let list=rotationsOf();if(!list.length)return '';let cur=selectedRotation();return `<select aria-label="Rotation" onchange="selectRotation(this.value)">${list.map(r=>`<option value="${r.id}" ${cur&&cur.id===r.id?'selected':''}>${esc(r.name)} · ${fmtDate(r.start)} – ${fmtDate(r.end)}${r.status==='Published'?' · Published':''}</option>`).join('')}<option value="" ${cur?'':'selected'}>Calendar month (no rotation)</option></select>`}
function selectRotation(v){rotationSel[dept]=v;let r=rotationById(v);if(r){cursor=date(r.start);if(mode==='Month')cursor.setDate(1)}else if(mode==='Rotation')mode='Month';render()}
function goToday(){cursor=new Date();cursor.setDate(1);let r=rotationFor(dept,iso(new Date()));if(r){rotationSel[dept]=r.id;if(mode==='Rotation')cursor=date(r.start)}render()}
function rotationDefaults(department=dept){return state.rotationDefaults[department]||{start:'',length:8,unit:'weeks'}}
function nextRotation(department=dept,list=rotationsOf(department)){let d=rotationDefaults(department),last=list[list.length-1],start=last?plus(last.end,1):d.start;if(!start)return null;let year=start.slice(0,4),n=list.filter(r=>r.start.slice(0,4)===year).length+1;return {id:id(),dept:department,name:`${year} Rotation ${n}`,start,end:addDuration(start,d.length,d.unit),status:'Draft',holidays:[]}}
function addRotations(count,withHolidays){count=Math.max(1,Math.min(26,count||1));let list=rotationsOf(),added=[];for(let i=0;i<count;i++){let r=nextRotation(dept,[...list,...added]);if(!r){toast('Set the default start date for '+organizationFor(dept).name+' first.');return}if(withHolidays)r.holidays=standardHolidaysBetween(r.start,r.end).map(h=>({id:id(),name:h.name,date:h.date,coverage:{}}));added.push(r)}let next=[...state.rotations,...added];try{validateRotations(next)}catch(e){toast(e.message);return}checkpoint();state.rotations=next;if(!rotationSel[dept])rotationSel[dept]=added[0].id;commit('Added '+added.length+(added.length===1?' rotation':' rotations')+' · '+organizationFor(dept).name);toast(added.length+(added.length===1?' rotation added':' rotations added'))}
function saveRotationDefaults(e){e.preventDefault();let f=new FormData(e.target),d={start:f.get('start'),length:+f.get('length'),unit:f.get('unit')},next={...state.rotationDefaults,[dept]:d};try{validateRotationDefaults(next)}catch(err){toast(err.message);return}checkpoint();state.rotationDefaults=next;commit('Saved rotation defaults · '+organizationFor(dept).name);toast('Rotation defaults saved')}
function holidayRow(h,types=activeTypes()){return `<div class="holiday-row" data-id="${esc(h.id)}"><div class="formgrid"><label>Holiday<input name="h-name" maxlength="60" required value="${esc(h.name)}" list="holiday-names"></label><label>Date<input type="date" name="h-date" required value="${esc(h.date)}"></label></div><div class="holiday-cov"><span class="muted">Required providers</span>${types.map(t=>`<label>${esc(t.name)}<input type="number" name="h-cov-${t.id}" min="0" max="10" step="1" placeholder="${t.coverage}" value="${h.coverage&&h.coverage[t.id]!=null?h.coverage[t.id]:''}"></label>`).join('')}</div><button type="button" class="danger" onclick="this.closest('.holiday-row').remove()">Remove holiday</button></div>`}
function rotationDialog(rid){let r=rotationById(rid);if(!r)return;let ro=r.status==='Published';modal(`<h2>${esc(r.name)}</h2><p>${esc(organizationFor(r.dept).name)} · ${ro?'Published — reopen it from the schedule to change its dates or holidays.':'Dates and holidays for this rotation only.'}</p><form onsubmit="saveRotation(event,'${r.id}')"><fieldset ${ro?'disabled':''} class="plain"><div class="formgrid"><label class="full">Name<input name="name" maxlength="60" required value="${esc(r.name)}"></label><label>Start date<input type="date" name="start" required value="${r.start}"></label><label>End date<input type="date" name="end" required value="${r.end}"></label><div class="full inline-length"><span class="muted">Or set the length:</span><input type="number" id="rot-len" min="1" max="366" placeholder="8" aria-label="Length"><select id="rot-unit" aria-label="Unit">${ROTATION_UNITS.map(u=>`<option ${u==='weeks'?'selected':''}>${u}</option>`).join('')}</select><button type="button" onclick="applyRotationLength()">Set end date</button></div></div><h3 style="margin-top:18px">Holidays in this rotation</h3><p class="muted">A holiday’s required providers replace the normal daily coverage for that shift type. Leave a box blank to keep the normal number (shown faintly).</p><datalist id="holiday-names">${[...new Set([...holidayNames(),...standardHolidays(2026).map(h=>h[0])])].map(n=>`<option value="${esc(n)}">`).join('')}</datalist><div id="holiday-rows">${(r.holidays||[]).slice().sort((a,b)=>a.date.localeCompare(b.date)).map(h=>holidayRow(h)).join('')}</div><button type="button" onclick="addHolidayRow()">+ Add holiday</button> <button type="button" onclick="addStandardHolidayRows()">+ Add standard US holidays in these dates</button></fieldset><div id="formerror" class="danger" role="alert"></div><div class="modalactions"><button type="button" onclick="closeModal()">${ro?'Close':'Cancel'}</button>${ro?'':'<button class="primary">Save rotation</button>'}</div></form>`)}
function applyRotationLength(){let n=+$('#rot-len').value,u=$('#rot-unit').value,s=$('#modal input[name=start]').value;if(!validDate(s)||!Number.isInteger(n)||n<1)return;$('#modal input[name=end]').value=addDuration(s,n,u)}
function addHolidayRow(h){$('#holiday-rows').insertAdjacentHTML('beforeend',holidayRow(h||{id:id(),name:'',date:$('#modal input[name=start]').value,coverage:{}}))}
function addStandardHolidayRows(){let s=$('#modal input[name=start]').value,e=$('#modal input[name=end]').value;if(!validDate(s)||!validDate(e)||e<s)return;let have=new Set([...document.querySelectorAll('#holiday-rows input[name=h-date]')].map(x=>x.value)),list=standardHolidaysBetween(s,e).filter(h=>!have.has(h.date));list.forEach(h=>addHolidayRow({id:id(),name:h.name,date:h.date,coverage:{}}));if(!list.length)toast('No additional standard holidays fall in these dates.')}
function saveRotation(e,rid){e.preventDefault();let old=rotationById(rid);if(!old)return;if(old.status==='Published'){$('#formerror').textContent='Reopen this rotation before changing it.';return}let f=new FormData(e.target),shown=activeTypes().map(t=>t.id);let holidays=[...document.querySelectorAll('#holiday-rows .holiday-row')].map(row=>{let prev=(old.holidays||[]).find(h=>h.id===row.dataset.id),coverage={};for(let [k,v] of Object.entries(prev?.coverage||{}))if(!shown.includes(k))coverage[k]=v;for(let t of shown){let v=row.querySelector(`input[name="h-cov-${t}"]`).value;if(v!=='')coverage[t]=+v}return {id:row.dataset.id,name:row.querySelector('input[name=h-name]').value.trim(),date:row.querySelector('input[name=h-date]').value,coverage}});let r={...old,name:f.get('name').trim(),start:f.get('start'),end:f.get('end'),holidays},next=state.rotations.map(x=>x.id===rid?r:x);try{validateRotations(next)}catch(err){$('#formerror').textContent=err.message;return}if(state.assignments.some(a=>a.dept===r.dept&&a.date>=r.start&&a.date<=r.end&&isPublished(a.dept,a.date))){$('#formerror').textContent='These dates include a published schedule. Reopen it first.';return}checkpoint();state.rotations=next;closeModal();commit('Saved rotation · '+r.name);toast('Rotation saved')}
function deleteRotation(rid){let r=rotationById(rid);if(!r)return;if(r.status==='Published'){toast('Reopen this rotation before deleting it.');return}modal(`<h2>Delete ${esc(r.name)}?</h2><p>The rotation and its holidays are removed. Assignments on these dates stay on the calendar.</p><div class="modalactions"><button onclick="closeModal()">Cancel</button><button class="primary danger" onclick="confirmDeleteRotation('${r.id}')">Delete rotation</button></div>`)}
function confirmDeleteRotation(rid){let r=rotationById(rid);if(!r||r.status==='Published')return;checkpoint();state.rotations=state.rotations.filter(x=>x.id!==rid);if(rotationSel[r.dept]===rid)delete rotationSel[r.dept];closeModal();commit('Deleted rotation · '+r.name);toast('Rotation deleted')}
function openRotation(rid){let r=rotationById(rid);if(!r)return;dept=r.dept;rotationSel[dept]=rid;cursor=date(r.start);mode='Rotation';if(!selectedOrgs.includes(organizationFor(dept).id))selectedOrgs=[...selectedOrgs,organizationFor(dept).id];navigate('Schedule')}
function saveHolidayHistory(e){e.preventDefault();let f=new FormData(e.target),x={id:id(),provider:f.get('provider'),holiday:f.get('holiday').trim(),year:+f.get('year')},next=[...state.holidayHistory,x];try{validateHolidayHistory(next,new Set(state.providers.map(p=>p.id)))}catch(err){toast('Enter a provider, holiday name, and a year from 1990 to 2100.');return}checkpoint();state.holidayHistory=next;commit('Recorded past holiday coverage · '+provider(x.provider).name+' · '+x.holiday+' '+x.year);toast('Past holiday coverage recorded')}
function removeHolidayHistory(hid){let x=state.holidayHistory.find(h=>h.id===hid);if(!x)return;checkpoint();state.holidayHistory=state.holidayHistory.filter(h=>h.id!==hid);commit('Removed past holiday coverage · '+x.holiday+' '+x.year)}
function rotationsPage(){let list=rotationsOf(),d=rotationDefaults(),org=organizationFor(dept).name,cov=r=>{let need=totalSlots(dept,r),gaps=coverageMissing(dept,r).length;return need?Math.round((need-gaps)/need*100)+'% covered':'No required shifts'};
 return title('Every rotation, planned ahead.','Each team sets its rotation length, then adds rotations and the holidays inside them.',`<button class="primary" onclick="addRotations(1,true)">+ Add next rotation</button>`)
 +`<div class="toolbar">${deptSelect()}</div>`
 +`<div class="below"><form class="panel" onsubmit="saveRotationDefaults(event)"><h3>Default rotation · ${esc(org)}</h3><p>New rotations start the day after the previous one ends and last this long. You can still change any rotation’s own dates.</p><div class="formgrid"><label>First rotation starts<input type="date" name="start" value="${esc(d.start||'')}" required></label><div class="inline-length"><label>Duration<input type="number" name="length" min="1" max="366" step="1" value="${d.length}" required></label><label>Unit<select name="unit">${ROTATION_UNITS.map(u=>`<option ${u===d.unit?'selected':''}>${u}</option>`).join('')}</select></label></div></div><p class="muted">${d.start?'A rotation starting '+fmtDate(d.start)+' ends '+fmtDate(addDuration(d.start,d.length,d.unit))+'.':'Set a start date to add rotations.'}</p><div style="text-align:right"><button class="primary">Save defaults</button></div></form>`
 +`<div class="panel"><h3>Plan ahead</h3><p>Add several rotations at once using the defaults. Six 8-week rotations cover about a year.</p><div class="inline-length"><label>Rotations to add<input type="number" id="rot-count" value="6" min="1" max="26"></label><label class="check"><input type="checkbox" id="rot-hol" checked>Include standard US holidays</label></div><button onclick="addRotations(+$('#rot-count').value,$('#rot-hol').checked)">Add rotations</button><p class="muted">Standard holidays: New Year’s Day, Memorial Day, Independence Day, Labor Day, Thanksgiving, Christmas Eve, Christmas Day, New Year’s Eve. Edit a rotation to change them.</p></div></div>`
 +`<div class="tablewrap" style="margin-top:20px"><table><thead><tr><th>Rotation</th><th>Dates</th><th>Length</th><th>Holidays</th><th>Coverage</th><th>Status</th><th></th></tr></thead><tbody>${list.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${fmtDate(r.start)} – ${fmtDate(r.end)}</td><td>${rotationLength(r)}</td><td>${(r.holidays||[]).slice().sort((a,b)=>a.date.localeCompare(b.date)).map(h=>esc(h.name)+' <small class="muted">'+h.date.slice(5)+'</small>').join('<br>')||'<span class="muted">None</span>'}</td><td>${cov(r)}</td><td><span class="pill ${r.status==='Published'?'green':''}">${r.status}</span></td><td><button onclick="openRotation('${r.id}')">Open</button> <button onclick="rotationDialog('${r.id}')">${r.status==='Published'?'View':'Edit'}</button> ${r.status==='Published'?'':`<button class="danger" onclick="deleteRotation('${r.id}')">Delete</button>`}</td></tr>`).join('')||`<tr><td colspan="7">No rotations for ${esc(org)} yet. Set the default start date, then add rotations.</td></tr>`}</tbody></table></div>`
 +`<div class="panel" style="margin-top:20px"><h3>Holiday coverage before CountSchedula</h3><p>Record who covered each holiday in past years so the generator can rotate holidays fairly from the start. Holidays worked in CountSchedula are counted automatically.</p><form class="inline-length" onsubmit="saveHolidayHistory(event)"><label>Provider<select name="provider" required>${state.providers.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label>Holiday<input name="holiday" required maxlength="60" list="past-holiday-names"></label><datalist id="past-holiday-names">${[...new Set([...holidayNames(),...standardHolidays(2026).map(h=>h[0])])].map(n=>`<option value="${esc(n)}">`).join('')}</datalist><label>Year<input type="number" name="year" required min="1990" max="2100" value="${new Date().getFullYear()-1}"></label><button class="primary">Record</button></form>${(state.holidayHistory||[]).length?`<div class="tablewrap" style="margin-top:12px"><table><thead><tr><th>Year</th><th>Holiday</th><th>Provider</th><th></th></tr></thead><tbody>${state.holidayHistory.slice().sort((a,b)=>b.year-a.year||a.holiday.localeCompare(b.holiday)).map(x=>`<tr><td>${x.year}</td><td>${esc(x.holiday)}</td><td>${esc(provider(x.provider)?.name||'Unknown')}</td><td><button onclick="removeHolidayHistory('${x.id}')">Remove</button></td></tr>`).join('')}</tbody></table></div>`:''}</div>`}
function holidayReport(){let P=period(),hs=P.kind==='rotation'?(P.rotation.holidays||[]).slice().sort((a,b)=>a.date.localeCompare(b.date)):[],names=holidayNames(),provs=state.providers.filter(p=>p.affiliations.includes(dept));
 let current=hs.length?`<table><thead><tr><th>Holiday</th><th>Date</th><th>Covered by</th></tr></thead><tbody>${hs.map(h=>{let a=state.assignments.filter(a=>a.dept===dept&&a.date===h.date);return `<tr><td>${esc(h.name)}</td><td>${fmtDate(h.date)}</td><td>${a.map(x=>esc(provider(x.provider)?.name)+' <small class="muted">'+esc(shiftName(x.shift))+'</small>').join('<br>')||'<span class="muted">Not yet assigned</span>'}</td></tr>`}).join('')}</tbody></table>`:'<p class="muted">No holidays in this scheduling period.</p>';
 let fair=names.length?`<div class="tablewrap"><table><thead><tr><th>Provider</th>${names.map(n=>`<th>${esc(n)}</th>`).join('')}<th>Total</th></tr></thead><tbody>${provs.map(p=>{let total=0;return `<tr><td><strong>${esc(p.name)}</strong></td>${names.map(n=>{let ys=holidayHistory(p.id,n);total+=ys.length;let repeat=ys.some((y,i)=>i&&y===ys[i-1]+1);return `<td>${ys.join(', ')||'—'}${repeat?' <span class="danger" title="Covered this holiday in consecutive years">⚠</span>':''}</td>`}).join('')}<td>${total}</td></tr>`}).join('')}</tbody></table></div><p class="muted">Years each provider covered each holiday (CountSchedula assignments plus recorded past coverage). ⚠ marks the same holiday in consecutive years. When filling a holiday shift the generator prefers providers who covered that holiday least recently and least often.</p>`:'<p class="muted">No holidays recorded yet.</p>';
 return `<div class="panel" style="margin-top:20px"><h3>Holidays · ${esc(P.label)}</h3>${current}<h3 style="margin-top:20px">Holiday fairness over the years · ${esc(organizationFor(dept).name)}</h3>${fair}</div>`}

/*@boot*/
if(CLOUD)CLOUD.boot();else if(!localStorage.getItem(KEY)){generate(true);history=[]}else{mode=defaultMode();render()}
